<?php require_once '../config/database.php';require_once '../includes/functions.php';require_admin();$pageTitle='Wishlist Data';$active='wishlist';$rows=$pdo->query("SELECT w.user_id,u.name user_name,u.email,w.product_id,p.name product_name,p.price,w.created_at FROM wishlist_items w JOIN users u ON u.id=w.user_id JOIN products p ON p.id=w.product_id ORDER BY w.created_at DESC")->fetchAll();require 'header.php';?><div class="admin-top"><div><span class="eyebrow">Store Data</span><h1>Wishlist</h1><p>Saved wishlist products for customers.</p></div></div><section class="admin-card"><div class="table-scroll"><table class="admin-table"><thead><tr><th>User</th><th>Email</th><th>Product</th><th>Price</th><th>Added</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['user_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['product_name'])?></td><td>₹<?=number_format((float)$r['price'],2)?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="empty-row">No saved wishlist data.</td></tr><?php endif;?></tbody></table></div></section><?php require 'footer.php';
